<section class="capability-directory section-pad" id="capabilities" data-service-directory><div class="wrap"><?php mnyphoto_section_intro( __( 'Capability directory', 'mnyphoto-theme' ), __( 'Thirty specific ways to move the image forward.', 'mnyphoto-theme' ), __( 'Every capability is linkable for briefs, bookmarks, and direct conversations.', 'mnyphoto-theme' ) ); ?><div class="capability-groups"><?php foreach ( mnyphoto_get_services() as $slug => $service ) : ?><section class="capability-group" aria-labelledby="capability-title-<?php echo esc_attr( $slug ); ?>"><header><span><?php echo esc_html( $service['number'] ); ?></span><h3 id="capability-title-<?php echo esc_attr( $slug ); ?>"><?php echo esc_html( $service['title'] ); ?></h3></header><div><?php foreach ( $service['capabilities'] as $id => $capability ) : ?><article class="capability-card" id="<?php echo esc_attr( $id ); ?>"><h4><?php echo esc_html( $capability ); ?></h4><p><?php echo esc_html( sprintf( __( 'Planning, production, and delivery tailored to %s.', 'mnyphoto-theme' ), strtolower( $capability ) ) ); ?></p></article><?php endforeach; ?></div></section><?php endforeach; ?></div></div></section>
